// The reference branch drops binary data, so re-attach the document
// binary and the engine label from the original form submission.
const form = $('On form submission').first();

$input.item.json.startMs = Date.now();
$input.item.json.engineLabel = form.json['Extraction Engine'];

// Find the uploaded document binary on the form item (the file that is NOT the reference)
const bins = form.binary || {};
const docKey =
  bins.Document_Upload ? 'Document_Upload' :
  bins['Document Upload'] ? 'Document Upload' :
  Object.keys(bins).find(k => !/reference/i.test(k));

if (!docKey || !bins[docKey]) {
  throw new Error('Document binary not found on the form item. Binary keys present: ' + Object.keys(bins).join(', '));
}

// Expose it under "data" (the name the easybits Extractor reads),
// and keep the original key too as a fallback.
$input.item.binary = {
  data: bins[docKey],
  [docKey]: bins[docKey],
};

return $input.item;

// ===== Code: Validate & Score (v2.1 - reference from Merge) =====
const MATCH_KEY = 'si';   // the column that identifies a row. Change if your id column is named differently.

// 1) Extracted side (the document under test)
const inp = $('Code: Shape Rows & Time').first().json;
const actualRows = inp.rows || [];
const engineLabel = inp.engineLabel;

// 2) Reference side (trusted CSV, or human-confirmed PDF, merged into one point)
const refRows = ($('Merge: Reference Ready').first().json.referenceRows || [])
  .map(r => (r && r.json) ? r.json : r);

// Fields to check = every reference column except the match key
const FIELDS = refRows.length ? Object.keys(refRows[0]).filter(k => k !== MATCH_KEY) : [];

// helpers
const collapse = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();
const isNullTok = (s) => ['', 'null', 'none', 'n/a', 'na'].includes(collapse(s).toLowerCase());
const eq = (a, b) => {
  const ca = collapse(a), cb = collapse(b);
  if (isNullTok(ca) && isNullTok(cb)) return true;   // NULL == null == empty
  return ca === cb;                                   // otherwise exact, case-sensitive
};

// index extracted rows by their match-key value
const byId = {};
for (const r of actualRows) byId[collapse(r[MATCH_KEY])] = r;

const mismatches = [];
const missingRows = [];
let checked = 0, correct = 0;

for (const exp of refRows) {
  const id = collapse(exp[MATCH_KEY]);
  const act = byId[id];
  if (!act) { missingRows.push(id); continue; }
  for (const f of FIELDS) {
    if (collapse(exp[f]) === '') continue;   // blank reference cell = skip (unknown). Put NULL to assert empty.
    checked++;
    if (eq(exp[f], act[f])) correct++;
    else mismatches.push({ id, field: f, expected: collapse(exp[f]), got: collapse(act[f]) || '(empty)' });
  }
}

const refIds = new Set(refRows.map(e => collapse(e[MATCH_KEY])));
const extraRows = actualRows.map(r => collapse(r[MATCH_KEY])).filter(id => id && !refIds.has(id));

const accuracy = checked ? +(100 * correct / checked).toFixed(2) : 0;
const pass = mismatches.length === 0 && missingRows.length === 0 && extraRows.length === 0;

const summary = pass
  ? `PASS - 100% (${correct}/${checked} cells) using ${engineLabel} in ${inp.elapsedSeconds}s`
  : `FAIL - ${accuracy}% (${correct}/${checked} cells) using ${engineLabel}, ${mismatches.length} mismatches, ${missingRows.length} missing rows, in ${inp.elapsedSeconds}s`;

const report = mismatches.map(m => `Row ${m.id} | ${m.field}: expected "${m.expected}" got "${m.got}"`).join('\n');

// styled HTML card
const statusColor = pass ? '#16a34a' : '#dc2626';
const statusBg    = pass ? '#f0fdf4' : '#fef2f2';
const statusEmoji = pass ? '🎉' : '⚠️';
const statusWord  = pass ? 'PASS' : 'FAIL';

const stat = (label, value) => `
  <div style="flex:1;min-width:120px;background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:16px;text-align:center;">
    <div style="font-size:24px;font-weight:700;color:#111827;">${value}</div>
    <div style="font-size:12px;color:#6b7280;margin-top:4px;text-transform:uppercase;letter-spacing:.04em;">${label}</div>
  </div>`;

const rowsHtml = mismatches.length
  ? `<table style="width:100%;border-collapse:collapse;margin-top:20px;font-size:13px;">
       <tr style="text-align:left;color:#6b7280;">
         <th style="padding:6px 8px;border-bottom:1px solid #e5e7eb;">Row</th>
         <th style="padding:6px 8px;border-bottom:1px solid #e5e7eb;">Field</th>
         <th style="padding:6px 8px;border-bottom:1px solid #e5e7eb;">Expected</th>
         <th style="padding:6px 8px;border-bottom:1px solid #e5e7eb;">Got</th>
       </tr>
       ${mismatches.map(m => `<tr>
         <td style="padding:6px 8px;border-bottom:1px solid #f3f4f6;">${m.id}</td>
         <td style="padding:6px 8px;border-bottom:1px solid #f3f4f6;">${m.field}</td>
         <td style="padding:6px 8px;border-bottom:1px solid #f3f4f6;color:#16a34a;">${m.expected}</td>
         <td style="padding:6px 8px;border-bottom:1px solid #f3f4f6;color:#dc2626;">${m.got}</td>
       </tr>`).join('')}
     </table>`
  : `<p style="margin:20px 0 0;text-align:center;color:#16a34a;font-size:14px;">Every checked cell matched your reference data.</p>`;

const html = `
<style>@keyframes pop{0%{transform:scale(.9);opacity:0}100%{transform:scale(1);opacity:1}}</style>
<div style="font-family:-apple-system,Segoe UI,Roboto,sans-serif;max-width:640px;margin:24px auto;padding:0 16px;animation:pop .35s ease-out;">
  <div style="background:${statusBg};border:1px solid ${statusColor}33;border-radius:16px;padding:28px;text-align:center;">
    <div style="font-size:48px;line-height:1;">${statusEmoji}</div>
    <div style="font-size:30px;font-weight:800;color:${statusColor};margin-top:8px;">${statusWord} &ndash; ${accuracy}%</div>
    <div style="font-size:14px;color:#6b7280;margin-top:6px;">${engineLabel}</div>
  </div>
  <div style="display:flex;gap:12px;flex-wrap:wrap;margin-top:16px;">
    ${stat('Cells correct', `${correct}/${checked}`)}
    ${stat('Rows read', `${actualRows.length}/${refRows.length}`)}
    ${stat('Time', `${inp.elapsedSeconds}s`)}
  </div>
  ${rowsHtml}
</div>`;

return [{ json: {
  pass,
  accuracy_pct: accuracy,
  cells_checked: checked,
  cells_correct: correct,
  rows_expected: refRows.length,
  rows_extracted: inp.rowCount,
  missing_rows: missingRows,
  extra_row_ids: extraRows,
  mismatch_count: mismatches.length,
  mismatches,
  engine_label: engineLabel,
  extraction_ms: inp.elapsedMs,
  extraction_seconds: inp.elapsedSeconds,
  summary,
  report,
  html,
} }];

const startMs = $('Code: Start Timer').first().json.startMs;
const engineLabel = $('Code: Start Timer').first().json.engineLabel;
const elapsedMs = Date.now() - Number(startMs);

const out = $input.first().json || {};
const data = out.data ?? out;               // Extractor wraps output in `data`

let rows = null;
if (Array.isArray(data)) rows = data;
else if (Array.isArray(data.records)) rows = data.records;
else if (Array.isArray(data.rows)) rows = data.rows;
else { for (const k of Object.keys(data)) { if (Array.isArray(data[k])) { rows = data[k]; break; } } }
if (!rows) rows = [];

const norm = (v) => (v === null || v === undefined) ? '' : String(v).trim();
const shaped = rows.map((r) => ({
  si: norm(r.si),
  new_tin: norm(r.new_tin),
  asses_name: norm(r.asses_name),
  father_name: norm(r.father_name),
  contact_email_address: norm(r.contact_email_address),
  current_address: norm(r.current_address),
}));

return [{ json: {
  engineLabel,
  elapsedMs,
  elapsedSeconds: +(elapsedMs / 1000).toFixed(2),
  rowCount: shaped.length,
  rows: shaped,
} }];

// CSV reference: already human-verified, trusted as-is
   const rows = ($('Aggregate Reference').first().json.data || [])
     .map(r => (r && r.json) ? r.json : r);
   return [{ json: { referenceRows: rows, source: 'csv' } }];

const out = $input.first().json || {};
const data = out.data ?? out;
let rows = Array.isArray(data) ? data
  : Array.isArray(data.records) ? data.records
  : (Object.values(data).find(Array.isArray) || []);

const norm = (v) => (v === null || v === undefined) ? '' : String(v).trim();
rows = rows.map(r => { const o = {}; for (const k of Object.keys(r)) o[k] = norm(r[k]); return o; });

const cols = rows.length ? Object.keys(rows[0]) : [];
const th = cols.map(c => `<th style="padding:10px 12px;background:#f9fafb;border-bottom:2px solid #eef2f7;text-align:left;font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.04em;color:#6b7280;white-space:nowrap;">${c}</th>`).join('');
const trs = rows.map((r, i) => `<tr style="background:${i % 2 ? '#fcfcfd' : '#fff'};">${cols.map(c => `<td style="padding:9px 12px;border-bottom:1px solid #f3f4f6;font-size:12.5px;color:#374151;">${r[c] || '<span style="color:#dc2626;font-style:italic;">empty</span>'}</td>`).join('')}</tr>`).join('');

const previewHtml = `
<div style="font-family:-apple-system,Segoe UI,Roboto,sans-serif;max-width:820px;margin:12px auto;">
  <div style="text-align:center;margin-bottom:20px;">
    <div style="font-size:34px;line-height:1;">🔍</div>
    <h2 style="font-size:22px;font-weight:800;color:#111827;margin:10px 0 4px;">Check your reference data</h2>
    <p style="font-size:14px;color:#6b7280;margin:0;">This is what was read from your reference file. It becomes the ground truth for the test, so every cell needs to be correct.</p>
  </div>
  <div style="background:#fffbeb;border:1px solid #fde68a;border-radius:10px;padding:12px 16px;margin-bottom:18px;font-size:13px;color:#92400e;">
    <b>Before you continue:</b> confirm the values below match the document exactly. IDs should keep any leading zeros, and empty cells should read <i>empty</i>. If anything is off, choose "No" and re-upload a corrected CSV.
  </div>
  <div style="border:1px solid #e5e7eb;border-radius:12px;overflow:hidden;">
    <div style="overflow-x:auto;">
      <table style="border-collapse:collapse;width:100%;">
        <thead><tr>${th}</tr></thead>
        <tbody>${trs}</tbody>
      </table>
    </div>
  </div>
  <p style="font-size:12px;color:#9ca3af;text-align:center;margin:14px 0 0;">${rows.length} row${rows.length === 1 ? '' : 's'} read from your file</p>
</div>`;

return [{ json: { referenceRows: rows, previewHtml } }];

// Human confirmed the extracted reference, so trust it
   const rows = $('Code: Shape Reference + Preview').first().json.referenceRows || [];
   return [{ json: { referenceRows: rows, source: 'pdf-confirmed' } }];
